public int alternatingCharacters(String s) {
    StringBuilder kept = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (kept.length() == 0 || kept.charAt(kept.length() - 1) != c) {
            kept.append(c);
        }
    }
    return s.length() - kept.length();
}

